import {indexGraph,connections,searchNodes,projectGraph,layoutGraph,edgePath} from './dependency-model.js';
import {createLinkInspector} from './dependency-inspector.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SYMBOLS={environment:'⌂',operations:'⚙',data:'▤',metrics:'◇'};
const value=v=>typeof v==='object'?JSON.stringify(v):String(v);

export function installDependencies(){
 if(document.querySelector('.dependency-launcher'))return;
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./dependencies.css',import.meta.url);document.head.append(css);
 const launch=document.createElement('button');launch.type='button';launch.className='dependency-launcher';launch.title='Explore variable dependencies';launch.setAttribute('aria-label','Explore variable dependencies');launch.setAttribute('aria-haspopup','dialog');launch.innerHTML='<span aria-hidden="true">i</span>';
 const header=document.querySelector('.top-actions')||document.querySelector('body > header, .studio-header');(header||document.body).append(launch);if(!header)launch.classList.add('is-floating');
 const dialog=document.createElement('dialog');dialog.className='dep-dialog';dialog.setAttribute('aria-labelledby','dep-title');document.body.append(dialog);
 let graph=null,pending=null,selected='kpi:invoice_timeliness',all=true,conditional=true,direction='both',expanded=new Set(),history=[],view={x:0,y:0,z:1},layout,projected,selection,activeResult=-1,results=[],opener=launch,pan=null,dragged=false,inspector=null;
 const $=s=>dialog.querySelector(s);
 async function load(){if(graph)return graph;if(pending)return pending;
  pending=(async()=>{const q=new URLSearchParams(location.search),api=(q.get('engine')||'').replace(/\/$/,'')+'/api';let data;
   try{const r=await fetch(api+'/dependencies',{signal:AbortSignal.timeout(4000)});if(!r.ok)throw Error('Map unavailable');data=await r.json();}
   catch{const r=await fetch(new URL('./dependency-graph.json',import.meta.url));if(!r.ok)throw Error('The dependency map could not load. Please retry.');data=await r.json();}
   if(data.schemaVersion!=='utility-dependencies/1.0')throw Error('This dependency map uses an unsupported version.');graph=indexGraph(data);return graph;})().finally(()=>pending=null);return pending;}
 function shell(){inspector?.destroy();dialog.innerHTML=`<header class="dep-header"><div class="dep-brand-mark" aria-hidden="true">◇</div><div><span class="dep-eyebrow">UTILITY STUDIO · ENGINE ATLAS</span><h1 id="dep-title">Variable dependencies</h1></div><button class="dep-close" type="button" aria-label="Close dependency explorer">×</button></header>
  <div class="dep-tools"><div class="dep-search-wrap"><span aria-hidden="true">⌕</span><input id="dep-search" type="search" role="combobox" aria-autocomplete="list" aria-controls="dep-results" aria-expanded="false" placeholder="Find a variable, setting or KPI…" autocomplete="off"><label class="dep-sr" for="dep-search">Find a variable, setting or KPI</label><div id="dep-results" role="listbox" aria-label="Matching variables" hidden></div></div><div class="dep-depth" role="group" aria-label="Connection depth"><button type="button" data-depth="direct" aria-pressed="${!all}">Direct links</button><button type="button" data-depth="all" aria-pressed="${all}">All paths</button></div><label class="dep-conditional"><input type="checkbox" id="dep-conditional" ${conditional?'checked':''}>Include conditional links</label></div>
  <div class="dep-body"><section class="dep-map-panel" aria-label="Dependency tree"><div class="dep-map-caption"><div><span class="dep-live-dot"></span><span id="dep-context">Loading engine relationships…</span></div><span>Hover shared paths to trace a link · drag to explore · scroll to zoom</span></div><div id="dep-viewport" tabindex="0" aria-label="Draggable dependency tree. Arrow keys pan; plus and minus zoom; Home fits the tree."><div id="dep-world"></div><p class="dep-load" role="status">Opening the engine atlas…</p></div><div class="dep-map-bottom"><div class="dep-legend"><span><i></i>Feeds into</span><span><i class="conditional"></i>Conditional / feedback</span><span class="dep-selected-key">◇ Selected</span></div><div class="dep-zoom"><button type="button" data-view="out" aria-label="Zoom out">−</button><output id="dep-scale">100%</output><button type="button" data-view="in" aria-label="Zoom in">+</button><button type="button" data-view="fit">Fit tree</button><button type="button" data-view="center">Center selected</button></div></div></section><aside id="dep-detail" aria-label="Selected variable"></aside></div>
  <footer class="dep-footer"><span>Inputs <b>→</b> Focus <b>→</b> Effects <b>→</b> KPIs <b>·</b> ↺ Same variable, repeated</span><button type="button" id="dep-about">About this map</button></footer><div class="dep-sr" id="dep-announcement" role="status" aria-live="polite"></div>`;
  inspector=createLinkInspector(dialog,{getGraph:()=>graph,trace:traceEdge});
  $('.dep-close').onclick=()=>dialog.close();$('#dep-search').oninput=search;$('#dep-search').onkeydown=searchKeys;
  dialog.querySelectorAll('[data-depth]').forEach(b=>b.onclick=()=>{all=b.dataset.depth==='all';dialog.querySelectorAll('[data-depth]').forEach(x=>x.setAttribute('aria-pressed',String((x.dataset.depth==='all')===all)));draw();});
  $('#dep-conditional').onchange=e=>{conditional=e.target.checked;draw();};
  dialog.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{const a=b.dataset.view;if(a==='fit')fit();else if(a==='center')center();else zoom(a==='in'?1.2:1/1.2);});
  $('#dep-about').onclick=()=>{const info=$('#dep-description');if(info){info.hidden=!info.hidden;if(!info.hidden)info.scrollIntoView({block:'nearest'});}};
  const collapse=document.createElement('button');collapse.type='button';collapse.id='dep-collapse';collapse.textContent='Collapse groups';collapse.hidden=true;collapse.onclick=()=>{expanded.clear();draw();};$('.dep-zoom').prepend(collapse);
  const overview=document.createElement('div');overview.className='dep-overview';overview.innerHTML='<span>MAP OVERVIEW <small>Click to travel</small></span><svg role="img" aria-label="Overview of the dependency tree"></svg>';$('#dep-viewport').append(overview);
  overview.onpointerdown=e=>{e.stopPropagation();const svg=overview.querySelector('svg');if(!layout||e.target.closest('span'))return;const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),vp=$('#dep-viewport');view.x=vp.clientWidth/2-point.x*view.z;view.y=vp.clientHeight/2-point.y*view.z;transform();};
  const vp=$('#dep-viewport');vp.addEventListener('wheel',e=>{e.preventDefault();const r=vp.getBoundingClientRect();zoom(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top);},{passive:false});
  vp.onpointerdown=e=>{dragged=false;if(e.button!==0||e.target.closest('.dep-overview'))return;pan={id:e.pointerId,x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};};
  vp.onpointermove=e=>{if(!pan)return;const dx=e.clientX-pan.x,dy=e.clientY-pan.y;if(Math.abs(dx)+Math.abs(dy)>4){dragged=true;vp.setPointerCapture(pan.id);vp.classList.add('is-dragging');}if(dragged){view.x=pan.vx+dx;view.y=pan.vy+dy;transform();}};
  const stop=()=>{pan=null;vp.classList.remove('is-dragging');};vp.onpointerup=stop;vp.onpointercancel=stop;
  vp.onkeydown=e=>{if(e.target!==vp)return;const moves={ArrowLeft:[70,0],ArrowRight:[-70,0],ArrowUp:[0,70],ArrowDown:[0,-70]};if(moves[e.key]){e.preventDefault();view.x+=moves[e.key][0];view.y+=moves[e.key][1];transform();}else if(['+','=','-','Home'].includes(e.key)){e.preventDefault();e.key==='Home'?fit():zoom(e.key==='-'?1/1.2:1.2);}};
  vp.onclick=e=>{if(dragged)return;const hit=e.target.closest('[data-link-bundle],[data-link-port]');if(hit){inspector.show(hitEdges(hit),e.clientX,e.clientY,{pin:true});return;}const b=e.target.closest('[data-node]');if(!b||dragged)return;const node=projected.nodes.find(n=>n.id===b.dataset.node);if(node.kind==='group'){expanded.add(node.groupKey);draw(node.members[0]?.id);}else select(node.nodeId);vp.focus({preventScroll:true});};
  vp.onfocusin=e=>{const b=e.target.closest('[data-node]');if(!b||pan)return;const r=b.getBoundingClientRect(),v=vp.getBoundingClientRect();if(r.left<v.left||r.right>v.right||r.top<v.top||r.bottom>v.bottom)center(b.dataset.node);};
 }
 function transform(){inspector?.transformed();if(!$('#dep-world'))return;$('#dep-world').style.transform=`translate(${view.x}px,${view.y}px) scale(${view.z})`;$('#dep-scale').textContent=Math.round(view.z*100)+'%';const rect=$('#dep-map-window'),vp=$('#dep-viewport');if(rect){rect.setAttribute('x',-view.x/view.z);rect.setAttribute('y',-view.y/view.z);rect.setAttribute('width',vp.clientWidth/view.z);rect.setAttribute('height',vp.clientHeight/view.z);}}
 function zoom(factor,x,y){const vp=$('#dep-viewport');x??=vp.clientWidth/2;y??=vp.clientHeight/2;const z=Math.max(.25,Math.min(1.8,view.z*factor)),ratio=z/view.z;view.x=x-(x-view.x)*ratio;view.y=y-(y-view.y)*ratio;view.z=z;transform();}
 function fit(){if(!layout)return;const vp=$('#dep-viewport');view.z=Math.max(.25,Math.min(1,(vp.clientWidth-48)/layout.width,(vp.clientHeight-30)/layout.height));view.x=(vp.clientWidth-layout.width*view.z)/2;view.y=(vp.clientHeight-layout.height*view.z)/2;transform();}
 function center(id=selected){const p=layout?.positions.get(id);if(!p)return;const vp=$('#dep-viewport');view.z=Math.max(.85,view.z);view.x=vp.clientWidth/2-(p.x+p.w/2)*view.z;if(layout.width*view.z>vp.clientWidth)view.x=Math.min(20,Math.max(vp.clientWidth-layout.width*view.z-20,view.x));view.y=layout.height*view.z>vp.clientHeight?Math.min(20,Math.max(vp.clientHeight-layout.height*view.z-20,vp.clientHeight/2-(p.y+p.h/2)*view.z)):Math.min(25,(vp.clientHeight-layout.height*view.z)/2);transform();}
 function frame(id=selected){fit();if(view.z<.55)center(id);}
 function select(id,{back=false}={}){if(!graph?.byId.has(id))return;if(id!==selected&&!back)history.push(selected);selected=id;expanded=new Set();$('#dep-results').hidden=true;$('#dep-search').setAttribute('aria-expanded','false');$('#dep-search').removeAttribute('aria-activedescendant');draw();}
 function draw(anchor=selected){if(!graph||!dialog.open)return;inspector?.close();selection=connections(graph,selected,{all,conditional,direction});projected=projectGraph(graph,selection,selected,expanded);layout=layoutGraph(projected);const n=graph.byId.get(selected);
  $('#dep-context').textContent=`${all?'All paths':'Direct connections'} · ${selection.visible.size.toLocaleString()} variables & calculations${projected.nodes.some(n=>n.repeated)?' · ↺ feedback repeats':''}`;
  const lines=layout.bundles.map((bundle,i)=>`<path class="dep-edge ${bundle.conditional?'is-conditional':''} ${bundle.edges.some(e=>e.source===selected||e.target===selected)?'is-near':''}" data-bundle="${i}" d="${bundle.d}"/>`).join('');
  const hits=layout.bundles.map((bundle,i)=>`<path class="dep-link-hit" data-link-bundle="${i}" d="${bundle.d}"/>`).join('')+layout.ports.map(p=>`<path class="dep-link-hit" data-link-port="${esc(p.id)}" data-side="${p.side}" d="${edgePath(p.points)}"/>`).join('');
  const ports=layout.ports.map(p=>`<path class="dep-port ${p.conditional?'is-conditional':''} ${p.id===selected?'is-near':''}" data-port="${esc(p.id)}" data-side="${p.side}" d="${edgePath(p.points)}" ${p.side==='in'?`marker-end="url(#dep-arrow${p.conditional?'-conditional':''})"`:''}/>`).join('');
  const conduits=layout.corridors.filter(c=>c.tracks).map(c=>{const h=c.tracks*layout.trackPitch+24;return `<rect class="dep-conduit" x="24" y="${c.y+(c.height-h)/2}" width="${layout.width-48}" height="${h}" rx="10"/>`;}).join('');
  const lanes=layout.lanes.map((l,i)=>`<div class="dep-lane dep-${l.theme}" style="left:${l.x}px;width:${l.width}px;height:${layout.height-28}px"><header><span>0${i+1}</span><strong>${esc(l.title)}</strong><small>${l.count} ${l.count===1?'node':'nodes'}</small></header></div>`).join('');
  const cards=projected.nodes.map(node=>{const p=layout.positions.get(node.id),sel=node.id===selected;return `<button type="button" class="dep-node dep-${node.lane} ${sel?'is-selected':''} ${node.kind==='group'?'is-group':''} ${node.repeated&&!sel?'is-repeated':''}" data-variable="${esc(node.nodeId)}" data-node="${esc(node.id)}" style="left:${p.x}px;top:${p.y}px;width:${p.w}px;height:${p.h}px" ${sel?'aria-current="true"':''} aria-label="${esc(node.title+(node.repeated?', repeated appearance of the same variable':'')+(node.kind==='group'?`, expand ${node.members.length} settings`:''))}"><span class="dep-node-icon" aria-hidden="true">${node.kind==='group'?'⊞':SYMBOLS[node.lane]}</span><span><small>${node.repeated&&!sel?'↺ ':''}${sel?'SELECTED':node.kind==='group'?node.members.length+' SETTINGS':node.kind==='metric'?'KPI':node.kind==='setting'?'INPUT':node.kind==='calculation'?'CALCULATION':'ENGINE DATA'}</small><strong>${esc(node.title)}</strong><em>${node.kind==='group'?'Expand group →':sel?'Follow its connections':node.repeated?(node.relation==='before'?'Before · same variable ↺':'After · same variable ↺'):node.relation==='before'?'Feeds into selection':'Feeds onward from selection'}</em></span></button>`;}).join('');
  $('#dep-world').innerHTML=lanes+`<svg class="dep-wires" width="${layout.width}" height="${layout.height}" aria-hidden="true"><defs><marker id="dep-arrow" markerWidth="6" markerHeight="6" refX="6" refY="3" orient="auto" markerUnits="userSpaceOnUse"><path d="M0,0 L6,3 L0,6 Z" fill="#627b6b"/></marker><marker id="dep-arrow-conditional" markerWidth="6" markerHeight="6" refX="6" refY="3" orient="auto" markerUnits="userSpaceOnUse"><path d="M0,0 L6,3 L0,6 Z" fill="#a08758"/></marker></defs>${conduits}${lines}${ports}${hits}<path class="dep-trace"/></svg>`+cards;
  const wires=$('.dep-wires');
  wires.onpointerover=e=>{const hit=e.target.closest('.dep-link-hit');if(hit&&!pan)inspector.show(hitEdges(hit),e.clientX,e.clientY);};
  wires.onpointerout=e=>{if(e.target.closest('.dep-link-hit'))inspector.hideSoon();};
  const mini=$('.dep-overview svg');mini.setAttribute('viewBox',`0 0 ${layout.width} ${layout.height}`);mini.innerHTML=layout.lanes.map(l=>`<rect x="${l.x}" y="12" width="${l.width-5}" height="${layout.height-28}" fill="#e3e9d7"/>`).join('')+projected.nodes.map(node=>{const p=layout.positions.get(node.id);return `<rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" rx="8" fill="${node.id===selected?'#cba344':node.lane==='metrics'?'#bc9d61':node.lane==='data'?'#a294bd':node.lane==='operations'?'#72a0a9':'#87a474'}"/>`;}).join('')+'<rect id="dep-map-window" fill="#ffffff30" stroke="#5f7952" stroke-width="12"/>';
  $('#dep-collapse').hidden=!expanded.size;$('.dep-load').hidden=true;renderDetail(n);frame(anchor);$('#dep-announcement').textContent=`${n.title}. ${selection.before.size} predecessors and ${selection.after.size} dependents${all?' across all paths':', directly connected'}.`;
 }
 function hitEdges(hit){return hit.dataset.linkBundle!==undefined?layout.bundles[Number(hit.dataset.linkBundle)].edges:projected.edges.filter(e=>e[hit.dataset.side==='in'?'target':'source']===hit.dataset.linkPort);}
 function traceEdge(edge){const wires=$('.dep-wires'),trace=$('.dep-trace');if(!trace)return;const points=edge&&layout?.routes.get(edge);if(!points){trace.removeAttribute('d');trace.removeAttribute('marker-end');wires.classList.remove('is-tracing');return;}trace.setAttribute('d',edgePath(points));trace.setAttribute('marker-end',`url(#dep-arrow${edge.conditional?'-conditional':''})`);trace.classList.toggle('is-conditional',edge.conditional);wires.classList.add('is-tracing');}
 function renderDetail(n){const incoming=(graph.incoming.get(selected)||[]).filter(e=>conditional||e.kind!=='conditional'),outgoing=(graph.outgoing.get(selected)||[]).filter(e=>conditional||e.kind!=='conditional');
  const detailEdges=[];
  const related=(edges,key)=>edges.length?`<ul>${edges.map(e=>{const t=graph.byId.get(e[key]),info=detailEdges.push(e)-1;return `<li><button type="button" data-select="${esc(t.id)}"><span class="dep-mini dep-${t.lane}">${SYMBOLS[t.lane]}</span><span>${esc(t.title)}<small>${e.kind==='definition'?'Defines the counting window':e.kind==='conditional'?'Conditional connection':e.kind==='influence'?'Declared KPI influence':e.kind==='component'?'Configuration component':e.kind==='measure'?'Used in the KPI formula':t.kind==='setting'?esc(t.id):'Engine dependency'}</small></span><b>›</b></button><button type="button" class="dep-link-how" data-link-info="${info}" aria-label="Explain ${esc(graph.byId.get(e.source).title)} to ${esc(graph.byId.get(e.target).title)}">How does this connect? ↗</button>${e.kind==='conditional'?`<p class="dep-condition-note">${esc(e.note)}</p>`:''}</li>`;}).join('')}</ul>`:`<p class="dep-empty">${key==='source'?(n.kind==='setting'?'Independent input. You choose its value; no model variable calculates it.':'No preceding relationships are declared for this node.'):'No downstream model relationship is declared.'}</p>`;
  $('#dep-detail').innerHTML=`<div class="dep-detail-top"><button type="button" id="dep-back" ${history.length?'':'disabled'}>← Back</button><span>${esc(graph.groups.find(g=>g.id===n.lane).title)}</span></div><span class="dep-detail-icon dep-${n.lane}" aria-hidden="true">${SYMBOLS[n.lane]}</span><h2>${esc(n.title)}</h2><code>${esc(n.id)}</code><p class="dep-definition">${esc(n.description)}</p>${n.impact?`<p class="dep-impact">${esc(n.impact)}</p>`:''}${n.formula?`<div class="dep-formula"><small>HOW IT IS CALCULATED</small><p>${esc(n.formula)}</p></div>`:''}${n.default!==undefined?`<div class="dep-default"><span>Engine default</span><strong>${esc(value(n.default))} ${esc(n.unit||'')}</strong></div>`:''}
   <div class="dep-counts"><button type="button" data-direction="before" aria-pressed="${direction==='before'}"><strong>${selection.before.size}</strong><span>Predecessors</span></button><button type="button" data-direction="after" aria-pressed="${direction==='after'}"><strong>${selection.after.size}</strong><span>Dependents</span></button></div><button class="dep-show-both" type="button" data-direction="both" ${direction==='both'?'disabled':''}>Show both directions</button>
   <details class="dep-neighbours" open><summary>Direct predecessors <span>${incoming.length}</span></summary>${related(incoming,'source')}</details><details class="dep-neighbours" open><summary>Direct dependents <span>${outgoing.length}</span></summary>${related(outgoing,'target')}</details>
   <details class="dep-source"><summary>Model reference</summary><p>${esc(n.reference)}</p>${n.reach?`<p>${esc(graph.reaches[n.reach])}</p>`:''}<p>Defaults describe the engine, not the current simulation’s edited values.</p></details><p id="dep-description" class="dep-about" hidden>${esc(graph.description)} Inputs sit to the left of the focus, effects to the right, and KPIs in one column. Cards marked ↺ are repeated appearances of the same variable in a feedback loop; no extra calculation is created. Shared paths carry multiple relationships: hover or click to choose one and trace its complete route.</p>`;
  dialog.querySelectorAll('[data-link-info]').forEach(b=>b.onclick=()=>{const link=detailEdges[Number(b.dataset.linkInfo)],edge=projected.edges.find(e=>e.links.includes(link)),r=b.getBoundingClientRect();inspector.show(edge?[{...edge,links:[link]}]:[link],r.left,r.top,{pin:true,focus:b});if(edge)traceEdge(edge);});
  $('#dep-back').onclick=()=>select(history.pop(),{back:true});dialog.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>select(b.dataset.select));dialog.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>{direction=b.dataset.direction;draw();});
 }
 function search(){const q=$('#dep-search').value;results=searchNodes(graph,q);activeResult=-1;const box=$('#dep-results');box.hidden=!q.trim();$('#dep-search').setAttribute('aria-expanded',String(!box.hidden));$('#dep-search').removeAttribute('aria-activedescendant');
  box.innerHTML=results.length?`<div class="dep-result-count" role="presentation">${results.length} matches${results.length>60?' · showing first 60':''}</div>`+results.slice(0,60).map((n,i)=>`<button type="button" role="option" aria-selected="false" id="dep-result-${i}" data-result="${i}"><span class="dep-mini dep-${n.lane}">${SYMBOLS[n.lane]}</span><span><strong>${esc(n.title)}</strong><small>${esc(n.id)} · ${esc(n.topic)}</small></span><span class="dep-result-kind">${esc(n.kind)}</span></button>`).join(''):'<p class="dep-no-results" role="status">No matching variables. Try “analysts”, “weather” or “invoice”.</p>';
  box.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const n=results[Number(b.dataset.result)];select(n.id);$('#dep-search').value='';$('#dep-viewport').focus();});}
 function searchKeys(e){if(e.key==='Escape'&&!$('#dep-results').hidden){e.preventDefault();e.stopPropagation();$('#dep-results').hidden=true;$('#dep-search').setAttribute('aria-expanded','false');return;}
  if(!['ArrowDown','ArrowUp','Enter'].includes(e.key)||!results.length||$('#dep-results').hidden)return;e.preventDefault();
  if(e.key==='Enter'){select(results[Math.max(0,activeResult)].id);$('#dep-search').value='';$('#dep-viewport').focus();return;}
  activeResult=Math.max(0,Math.min(Math.min(results.length,60)-1,activeResult+(e.key==='ArrowDown'?1:-1)));$('#dep-search').setAttribute('aria-activedescendant','dep-result-'+activeResult);$('#dep-results').querySelectorAll('[role=option]').forEach((el,i)=>el.setAttribute('aria-selected',String(i===activeResult)));$('#dep-result-'+activeResult)?.scrollIntoView({block:'nearest'});}
 async function open(id){opener=document.activeElement;shell();dialog.showModal();document.documentElement.classList.add('dep-is-open');$('#dep-search').disabled=true;$('#dep-search').focus();
  try{await load();if(id&&graph.byId.has(id))selected=id;draw();$('#dep-search').disabled=false;$('#dep-search').focus();}
  catch(e){$('.dep-load').innerHTML=`${esc(e.message)} <button type="button" id="dep-retry">Retry</button>`;$('#dep-retry').onclick=async()=>{dialog.close();open(id);};}}
 launch.onclick=()=>open();dialog.onclose=()=>{inspector?.close();document.documentElement.classList.remove('dep-is-open');opener?.focus();};
 dialog.addEventListener('click',e=>{if(!e.target.closest('.dep-search-wrap')&&$('#dep-results')){$('#dep-results').hidden=true;$('#dep-search').setAttribute('aria-expanded','false');}});
 document.addEventListener('utility:dependencies',e=>{if(dialog.open)select(e.detail?.id);else open(e.detail?.id);});
 window.addEventListener('resize',()=>{if(dialog.open)frame();});
 return {open};
}
if(typeof document!=='undefined')installDependencies();
